#include <iostream>
#include <cstdint>

// Naive exponential recursion: O(2^n) calls
uint64_t fibNaive(uint32_t n, uint64_t& callCount) {
    ++callCount;
    if (n <= 1) {
        return n;
    }
    // In C++, the order of evaluating fibNaive(n-1) vs fibNaive(n-2) is unspecified
    return fibNaive(n - 1, callCount) + fibNaive(n - 2, callCount);
}

// Optimized tail recursion: O(n) linear complexity
uint64_t fibLinear(uint32_t n, uint64_t a = 0, uint64_t b = 1) {
    if (n == 0) return a;
    if (n == 1) return b;
    return fibLinear(n - 1, b, a + b);
}

int main() {
    uint32_t n = 0;
    if (!(std::cin >> n)) {
        return 0;
    }

    uint64_t callCount = 0;
    uint64_t naiveRes = fibNaive(n, callCount);
    uint64_t linearRes = fibLinear(n);

    std::cout << "Fibonacci(" << n << ") = " << naiveRes << "\n";
    std::cout << "Naive calls: " << callCount << "\n";
    std::cout << "Linear result: " << linearRes << "\n";
    return 0;
}

#include <iostream>
#include <cstdint>

// Iterative factorial: avoids call-stack frame overhead
uint64_t factorialIterative(uint32_t n) {
    uint64_t result = 1;
    for (uint32_t i = 2; i <= n; ++i) {
        result *= i;
    }
    return result;
}

// Recursive factorial: directly mirrors mathematical definition n!
uint64_t factorialRecursive(uint32_t n) {
    if (n <= 1) {
        return 1; // Base case
    }
    return n * factorialRecursive(n - 1); // Recursive step
}

int main() {
    uint32_t n = 0;
    if (!(std::cin >> n)) {
        return 0;
    }

    uint64_t iterRes = factorialIterative(n);
    uint64_t recRes = factorialRecursive(n);

    std::cout << "Iterative factorial: " << iterRes << "\n";
    std::cout << "Recursive factorial: " << recRes << "\n";
    return 0;
}
